fn frame(t: i32) {
    host::display::clear(0x050008);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let mut arm: i32 = 0;
    while arm < 8 {
        let base: i32 = arm * 32 + t / 2;
        let mut j: i32 = 0;
        while j < 7 {
            let r: i32 = 24 + j * 18 + (10 * host::math::sin(t * 2 + j * 24)) / 256;
            let a: i32 = base + (12 * host::math::sin(t + j * 40)) / 256;
            let x: i32 = cx + (r * host::math::cos(a)) / 256;
            let y: i32 = cy + (r * host::math::sin(a)) / 256;
            let s: i32 = 3 + j / 2;
            let col: i32 = if (arm & 1) == 0 { 0xff66aa } else { 0x66ccff };
            host::display::fill_rect(x - s / 2, y - s / 2, s, s, col);
            j = j + 1;
        }
        arm = arm + 1;
    }
    host::display::fill_rect(cx - 4, cy - 4, 8, 8, 0xffffff);
    host::display::present();
}
